static async Task<(int Customers, int Orders)> Counts(ShopDb db, CancellationToken ct)
{
    var customers = db.Customers.CountAsync(ct);
    var orders = db.Orders.CountAsync(ct);
    await Task.WhenAll(customers, orders);
    return (customers.Result, orders.Result);
}

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

app.Run();

